package com.weather.system.config;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Component public class JwtUtil { @Value("${jwt.secret}") private String secret; @Value("${jwt.expire-hours}") private long expireHours; private SecretKey key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String create(String username,String role){Date now=new Date(); return Jwts.builder().setSubject(username).claim("role",role).setIssuedAt(now).setExpiration(new Date(now.getTime()+expireHours*3600000)).signWith(key()).compact();} public Claims parse(String token){return Jwts.parserBuilder().setSigningKey(key()).build().parseClaimsJws(token).getBody();} }
